previewCss:
.darma-loader-darma-b8-dot-grid-wave { --accent: var(--loader-color, #06b6d4); width: var(--loader-size, 72px); height: var(--loader-size, 72px); display: grid; grid-template-columns: repeat(3, 1fr); gap: 14%; place-items: center; }
.darma-loader-darma-b8-dot-grid-wave span { width: 100%; aspect-ratio: 1; border-radius: 50%; background: var(--accent); animation: darma-loader-darma-b8-dot-grid-wave-gwave calc(var(--loader-speed, 1s) * 1.3) ease-in-out infinite; }
.darma-loader-darma-b8-dot-grid-wave span:nth-child(1) { animation-delay: 0s; }
.darma-loader-darma-b8-dot-grid-wave span:nth-child(2), .darma-loader-darma-b8-dot-grid-wave span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .12); }
.darma-loader-darma-b8-dot-grid-wave span:nth-child(3), .darma-loader-darma-b8-dot-grid-wave span:nth-child(5), .darma-loader-darma-b8-dot-grid-wave span:nth-child(7) { animation-delay: calc(var(--loader-speed, 1s) * .24); }
.darma-loader-darma-b8-dot-grid-wave span:nth-child(6), .darma-loader-darma-b8-dot-grid-wave span:nth-child(8) { animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b8-dot-grid-wave span:nth-child(9) { animation-delay: calc(var(--loader-speed, 1s) * .48); }
@keyframes darma-loader-darma-b8-dot-grid-wave-gwave { 0%, 100% { transform: scale(.4); opacity: .35; } 50% { transform: scale(1); opacity: 1; } }

